<template><ElConfigProvider namespace="kel"><section class="native-flow-header"><header><div class="identity"><button class="back" aria-label="返回作业平台" @click="emit('back')">←</button><div><h1><button class="name-edit" :disabled="!canEdit" @click="metadataOpen=true">{{name||'命名新交付任务'}}<small v-if="canEdit">✎</small></button><span :class="['state',state.toLowerCase()]"><i/>{{({ENABLED:'已启用',DISABLED:'已停用',DRAFT:'草稿',NEW:'新草稿'} as any)[state]}}</span></h1><div class="meta"><code>{{flow?.namespace||'Namespace 由项目确定'}} / {{flow?.flow_id||'新定义'}}</code><span>Revision {{flow?.revision||'—'}}</span></div></div></div><div class="actions"><template v-if="tab==='Builder'||dirty"><KsButton :disabled="busy" @click="emit('validate')">✓ 校验</KsButton><KsButton :disabled="!canEdit||busy" @click="name.trim()?emit('save',true):metadataOpen=true">保存草稿</KsButton></template><KsButton v-else :disabled="!canEdit" @click="emit('tab','Builder')">打开编辑器</KsButton><KsButton type="primary" :disabled="!canExecute||!flow||flow.disabled||flow.draft" @click="emit('run')">▷ 运行</KsButton><details class="actions-menu"><summary aria-label="Flow 更多操作">•••</summary><div><button :disabled="!canEdit||busy" @click="metadataOpen=true">编辑名称与说明</button><button :disabled="!canEdit||busy" @click="name.trim()?emit('save',false):metadataOpen=true">发布当前修订</button></div></details></div></header><nav v-if="flow"><button v-for="item in primary" :key="item[0]" :class="{active:tab===item[0]}" @click="emit('tab',item[0])">{{item[1]}}</button><select aria-label="更多 Flow 视图" :value="more.some(t=>t[0]===tab)?tab:''" @change="emit('tab',($event.target as HTMLSelectElement).value)"><option value="" disabled>更多</option><option v-for="item in more" :key="item[0]" :value="item[0]">{{item[1]}}</option></select><span class="dirty" v-if="dirty">● 未保存修改</span></nav>
<KsDialog v-model="metadataOpen" :teleported="false" :appendToBody="false" title="Flow 信息" width="520px"><div class="metadata-form"><label>名称<KsInput :modelValue="name" :disabled="!canEdit" @update:modelValue="v=>emit('metadata',{name:v})"/></label><label>说明<KsInput :modelValue="description||''" type="textarea" :disabled="!canEdit" @update:modelValue="v=>emit('metadata',{description:v})"/></label><label>目标类型<select :value="target" :disabled="!canEdit" @change="emit('metadata',{target:($event.target as HTMLSelectElement).value})"><option value="server">Server</option><option value="switch">Switch</option><option value="both">Mixed</option></select></label></div><template #footer><KsButton @click="metadataOpen=false">返回编辑器</KsButton></template></KsDialog></section></ElConfigProvider></template>
<script setup lang="ts">
import {computed,ref} from 'vue';import {ElConfigProvider} from 'element-plus';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';import KsDialog from '../../vendor/kestra/design-system/components/Feedback/KsDialog.vue';
const props=defineProps<{name:string;description?:string;target?:string;flow?:any;project:string;tab:string;canEdit:boolean;canExecute:boolean;dirty:boolean;busy?:boolean}>(),emit=defineEmits(['back','tab','run','metadata','save','validate']);const state=computed(()=>!props.flow?'NEW':props.flow.draft?'DRAFT':props.flow.disabled?'DISABLED':'ENABLED'),metadataOpen=ref(false);
const primary=[['Overview','Overview'],['Builder','Builder'],['Executions','Executions'],['Revisions','Revisions'],['Triggers','Triggers']],more=[['Dependencies','依赖'],['Logs','日志'],['Metrics','指标'],['Concurrency','并发与排队']];
</script>
<style scoped>.native-flow-header{font-family:var(--ks-font-family-sans);color:var(--ks-text-primary);background:transparent}.native-flow-header header{display:flex;align-items:center;justify-content:space-between;padding:16px 0 23px;gap:20px;height:auto;border:0;background:transparent}.identity{display:flex;align-items:center;gap:14px;min-width:0}h1{display:flex;align-items:center;gap:12px;font-size:23px;line-height:1.4;margin:0 0 6px;letter-spacing:-.4px}.back{font-size:19px;color:var(--ks-text-secondary);border:1px solid var(--ks-border-default);height:30px;width:30px;border-radius:5px}.state{display:flex;align-items:center;gap:6px;color:var(--ks-text-secondary);font-size:10px;font-weight:400;white-space:nowrap}.state i{height:5px;width:5px;border-radius:50%;background:currentColor}.state.enabled{color:var(--ks-text-success)}.state.draft{color:var(--ks-text-warning)}.meta,.actions{display:flex;align-items:center;gap:14px}.meta{color:var(--ks-text-secondary);font-size:10px}.meta>span{border-left:1px solid var(--ks-border-default);padding-left:14px}nav{display:flex;gap:28px;min-height:47px;align-items:stretch;border-bottom:1px solid var(--ks-border-default);font-size:11px;margin-bottom:15px}nav>button{padding:10px 0;color:var(--ks-text-secondary);border-bottom:2px solid transparent}nav>button.active{border-color:var(--ks-text-link);color:var(--ks-text-primary);font-weight:600}select{background:var(--ks-bg-input);border:1px solid var(--ks-border-default);border-radius:4px;color:var(--ks-text-primary);padding:5px;font-size:11px;align-self:center}.dirty{margin-left:auto;font-size:10px;color:var(--ks-text-warning);align-self:center}.actions-menu{position:relative}.actions-menu summary{list-style:none;padding:7px 10px;cursor:pointer}.actions-menu>div{position:absolute;right:0;top:34px;z-index:40;min-width:150px;padding:5px;border:1px solid var(--ks-border-default);border-radius:5px;background:var(--ks-bg-elevated);box-shadow:0 8px 24px #0002;display:grid;gap:3px}.actions-menu button{padding:8px;font-size:11px;text-align:left;white-space:nowrap}.actions-menu button:hover{background:var(--ks-bg-tag-inactive)}.metadata-form{display:grid;gap:18px}.metadata-form label{font-size:12px}.metadata-form :deep(.kel-input),.metadata-form select{display:block;margin-top:8px;width:100%}@media(max-width:1050px){nav{gap:16px}.actions{gap:6px}h1{font-size:20px}}</style>

<style scoped>.name-edit{font:inherit;letter-spacing:inherit;color:inherit;display:flex;gap:8px;align-items:center}.name-edit small{font-size:12px;color:var(--ks-text-secondary)}</style>
